import { Routes } from '@angular/router';
import { ReunionesComponent } from './reuniones/reuniones.component';

export const routes: Routes = [
  { path: '', redirectTo: '/reuniones', pathMatch: 'full' },
  { path: 'reuniones', component: ReunionesComponent },
  { path: 'inicio', component: ReunionesComponent },
  { path: 'calendario', component: ReunionesComponent },
  { path: 'historial', component: ReunionesComponent },
  { path: 'contactos', component: ReunionesComponent },
  { path: 'configuracion', component: ReunionesComponent }
];
